//! The DIFFERENTIAL GATE: Lean's own evaluation is the semantics
//! authority over the SHIPPED wasm. The manifest (target/diff.json) is
//! generated by the wasm-backend's oracle program — real Lean functions
//! evaluated over generated inputs; this test replays every row against
//! the emitted component via wasmtime. A backend bug = a failing row.

#![allow(
    clippy::disallowed_methods,
    reason = "tokio::test codegen, not our code"
)]

use steel_host::{CapabilitySet, ComponentRuntime, SteelEngine};
use wasmtime::component::Val;

fn manifest() -> &'static str {
    let p = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../lean/wasm-backend/target/diff.json");
    let p = std::fs::canonicalize(&p).expect("run `just wasm-compile` (generates diff.json)");
    Box::leak(std::fs::read_to_string(p).unwrap().into_boxed_str())
}

#[tokio::test]
async fn lean_semantics_govern_the_shipped_wasm() -> Result<(), Box<dyn std::error::Error>> {
    let rows: Vec<serde_json::Value> = serde_json::from_str(manifest())?;
    assert!(
        rows.len() >= 100,
        "oracle generated only {} rows — vacuous",
        rows.len()
    );
    // Negative control baked into the generator: the inputs include 0 and
    // values on BOTH sides of is-big's 100 threshold — zero area etc.

    let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../lean/wasm-backend/target/demo.component.wasm");
    let path = std::fs::canonicalize(&path)?;
    let engine = SteelEngine::new()?;
    let component = engine.load_component(&path)?;
    let mut rt = ComponentRuntime::new(engine.clone(), CapabilitySet::NONE).await?;
    rt.instantiate(&component).await?;

    let mut failures: Vec<String> = Vec::new();
    for row in &rows {
        let f = row["fn"].as_str().expect("fn");
        let args: Vec<Val> = row["args"]
            .as_array()
            .expect("args")
            .iter()
            .enumerate()
            .map(|(i, a)| match (f, i, a.as_str().expect("arg str")) {
                // pick's FIRST arg is the bool (canonical: flat i32 0/1)
                (_, 0, "0" | "1") if f == "pick" => Val::Bool(a.as_str() == Some("1")),
                (_, _, s) => Val::U64(s.parse::<u64>().expect("u64 arg")),
            })
            .collect::<Vec<Val>>();
        let expected = row["expected"].as_str().expect("expected");
        let got = rt.call(f, &args).await;
        match got {
            Ok(results) => {
                let gotStr = match &results[0] {
                    Val::U64(v) => v.to_string(),
                    Val::Bool(b) => {
                        if *b {
                            "1".to_string()
                        } else {
                            "0".to_string()
                        }
                    }
                    other => {
                        failures.push(format!(
                            "{f} {:?}: unexpected result {other:?}",
                            row["args"]
                        ));
                        continue;
                    }
                };
                if gotStr != expected {
                    failures.push(format!(
                        "{f} {:?}: expected {expected}, got {gotStr}",
                        row["args"]
                    ));
                }
            }
            Err(e) => failures.push(format!("{f} {:?}: TRAP {e}", row["args"])),
        }
    }
    assert!(
        failures.is_empty(),
        "{} differential failures:\n{}",
        failures.len(),
        failures.join("\n")
    );
    Ok(())
}
